L["Edge pulse"] = "Pulsation des bords"
L["Edge reach"] = "Portée des bords"
L["Edge:"] = "Bord :"
L["Edges creep in over"] = "Les bords s'insinuent en"
L["Edges lift as you near your body"] = "Les bords se lèvent près de votre corps"
L["Edges reach in"] = "Les bords s'avancent de"
L["Edit"] = "Modifier"
